mapper.update:
UPDATE aro_personnel
SET allowed_rooms_display_zh = #{text},
    has_official_room_permission = #{hasOfficialRoomPermission},
    update_time = #{currentTime}
WHERE user_id = #{userId}

UPDATE aro_personnel
SET personal_pin = #{pinHash},
    pin_updated_at = #{now}
WHERE user_id = #{userId}
  AND personal_pin IS NULL

mapper.select:
SELECT user_id, contact_email FROM aro_personnel
WHERE user_id IN #{id}
AND contact_email IS NOT NULL AND contact_email != ''

SELECT user_id, send_key FROM aro_personnel
WHERE user_id IN #{id}
AND send_key IS NOT NULL AND send_key != ''

SELECT user_id, wx_pusher_uid FROM aro_personnel
WHERE user_id IN #{id}
AND wx_pusher_uid IS NOT NULL AND wx_pusher_uid != ''

SELECT user_id FROM aro_personnel
WHERE contact_email = #{contactEmail}
LIMIT 1
